#!/usr/bin/env node
import fs from 'node:fs/promises';
import path from 'node:path';
const BBOX={west:-121.90,south:37.48,east:-121.74,north:37.60};
const AOI_NAME='Sunol Ridge Training Area';
const OUT='resources/palantir_sunol_aoi_upload';
const retrieved_at=new Date().toISOString();
const overpassUrl='https://overpass-api.de/api/interpreter';
const cecUrl=`https://services.gis.ca.gov/arcgis/rest/services/Boundaries/CAElectricTransmissionLines/FeatureServer/0/query?where=1%3D1&outFields=*&f=geojson&geometry=${BBOX.west},${BBOX.south},${BBOX.east},${BBOX.north}&geometryType=esriGeometryEnvelope&inSR=4326&spatialRel=esriSpatialRelIntersects`;
const hifldUrl=`https://services7.arcgis.com/mOBPykOjAyBO2ZKk/arcgis/rest/services/Electric_Power_Transmission_Lines/FeatureServer/0/query?where=1%3D1&outFields=*&f=geojson&geometry=${BBOX.west},${BBOX.south},${BBOX.east},${BBOX.north}&geometryType=esriGeometryEnvelope&inSR=4326&spatialRel=esriSpatialRelIntersects`;
const ensure=(p)=>fs.mkdir(p,{recursive:true});
const writeJSON=(p,obj)=>fs.writeFile(p,JSON.stringify(obj,null,2)+'\n');
const featureCollection=(features)=>({type:'FeatureCollection',features});
const withMeta=(fc,source_name,source_url)=>{for(const f of fc.features){f.properties={...(f.properties||{}),source_name,source_url,retrieved_at,provisional:true};}return fc;};
const fetchJson=async(url,opts)=>{const r=await fetch(url,opts); if(!r.ok) throw new Error(`HTTP ${r.status} ${url}`); return r.json();};
const overpass=async(query)=>{const body=new URLSearchParams({data:query}); const r=await fetch(overpassUrl,{method:'POST',body}); if(!r.ok) throw new Error(`Overpass ${r.status}`); return r.json();};
const osmtogeo=(data)=>{const feats=[]; for(const e of data.elements){ if(e.type==='node') feats.push({type:'Feature',geometry:{type:'Point',coordinates:[e.lon,e.lat]},properties:e.tags||{}}); if(e.type==='way'&&e.geometry) feats.push({type:'Feature',geometry:{type:'LineString',coordinates:e.geometry.map(g=>[g.lon,g.lat])},properties:e.tags||{}});} return featureCollection(feats);};

await Promise.all(['','/aoi','/osm','/official_power','/terrain','/mission_fixture'].map(s=>ensure(OUT+s)));
const aoi=featureCollection([{type:'Feature',geometry:{type:'Polygon',coordinates:[[[BBOX.west,BBOX.south],[BBOX.east,BBOX.south],[BBOX.east,BBOX.north],[BBOX.west,BBOX.north],[BBOX.west,BBOX.south]]]},properties:{name:AOI_NAME,source_name:'Synthetic AOI',source_url:'local',retrieved_at,provisional:true}}]);
await writeJSON(path.join(OUT,'aoi/sunol_training_area_aoi.geojson'),aoi);
const q=(sel)=>`[out:json][timeout:120];(way[${sel}](${BBOX.south},${BBOX.west},${BBOX.north},${BBOX.east});node[${sel}](${BBOX.south},${BBOX.west},${BBOX.north},${BBOX.east}););out geom;`;
const osmLayers={
  'osm_power_lines.geojson':q('"power"="line"'),'osm_power_towers_poles.geojson':q('"power"~"tower|pole"'),'osm_roads_tracks_paths.geojson':q('"highway"'),'osm_buildings.geojson':q('"building"'),'osm_natural_features.geojson':q('"natural"'),'osm_waterways_barriers.geojson':q('"waterway"')
};
const counts={};
for(const [f,qq] of Object.entries(osmLayers)){let fc=featureCollection([]);try{fc=withMeta(osmtogeo(await overpass(qq)),'OpenStreetMap Overpass',overpassUrl);}catch{fc=featureCollection([]);}counts['osm/'+f]=fc.features.length;await writeJSON(path.join(OUT,'osm',f),fc);}
for(const [f,u,s] of [['cec_transmission_lines.geojson',cecUrl,'California Energy Commission ArcGIS'],['hifld_transmission_lines.geojson',hifldUrl,'HIFLD ArcGIS']]){let fc=featureCollection([]);try{fc=withMeta(await fetchJson(u),s,u);}catch{fc=featureCollection([]);}counts['official_power/'+f]=fc.features.length;await writeJSON(path.join(OUT,'official_power',f),fc);}
let csv='lon,lat,elevation_m,source_name,source_url,retrieved_at,provisional\n';
for(let lat=BBOX.south;lat<=BBOX.north+1e-9;lat+=0.015){for(let lon=BBOX.west;lon<=BBOX.east+1e-9;lon+=0.015){const u=`https://epqs.nationalmap.gov/v1/json?x=${lon}&y=${lat}&units=Meters&wkid=4326&includeDate=false`;let elev='';try{elev=(await fetchJson(u)).value??'';}catch{}csv+=`${lon},${lat},${elev},USGS EPQS,https://epqs.nationalmap.gov,${retrieved_at},true\n`;}}
await fs.writeFile(path.join(OUT,'terrain/elevation_samples_500m.csv'),csv);counts['terrain/elevation_samples_500m.csv']=csv.trim().split('\n').length-1;
const tap=featureCollection([{type:'Feature',geometry:{type:'Point',coordinates:[-121.84,37.55]},properties:{attention_type:'scout_high_ground'}}]);withMeta(tap,'Synthetic mission fixture','local');await writeJSON(path.join(OUT,'terrain/terrain_attention_points.geojson'),tap);counts['terrain/terrain_attention_points.geojson']=1;
const fixtures={'synthetic_unit_route.geojson':featureCollection([{type:'Feature',geometry:{type:'LineString',coordinates:[[-121.89,37.50],[-121.84,37.54],[-121.78,37.58]]},properties:{name:'unit_route'}}]),'synthetic_drone_waypoints.geojson':featureCollection([{type:'Feature',geometry:{type:'Point',coordinates:[-121.86,37.52]},properties:{seq:1}},{type:'Feature',geometry:{type:'Point',coordinates:[-121.80,37.57]},properties:{seq:2}}]),'synthetic_route_branches.geojson':featureCollection([{type:'Feature',geometry:{type:'LineString',coordinates:[[-121.88,37.51],[-121.82,37.55]]},properties:{branch:'A'}},{type:'Feature',geometry:{type:'LineString',coordinates:[[-121.88,37.51],[-121.79,37.56]]},properties:{branch:'B'}}]),'synthetic_cue_zones.geojson':featureCollection([{type:'Feature',geometry:{type:'Polygon',coordinates:[[[-121.855,37.545],[-121.845,37.545],[-121.845,37.555],[-121.855,37.555],[-121.855,37.545]]]},properties:{cue:'2pps'}}]),'synthetic_no_go_zones.geojson':featureCollection([{type:'Feature',geometry:{type:'Polygon',coordinates:[[[-121.81,37.535],[-121.80,37.535],[-121.80,37.545],[-121.81,37.545],[-121.81,37.535]]]},properties:{reason:'powerline_buffer'}}])};
for(const [n,fc] of Object.entries(fixtures)){withMeta(fc,'Synthetic mission fixture','local');await writeJSON(path.join(OUT,'mission_fixture',n),fc);counts['mission_fixture/'+n]=fc.features.length;}
const files=['README.md','PALANTIR_UPLOAD_PROMPT.md','manifest.json','aoi/sunol_training_area_aoi.geojson','osm/osm_power_lines.geojson','osm/osm_power_towers_poles.geojson','osm/osm_roads_tracks_paths.geojson','osm/osm_buildings.geojson','osm/osm_natural_features.geojson','osm/osm_waterways_barriers.geojson','official_power/cec_transmission_lines.geojson','official_power/hifld_transmission_lines.geojson','terrain/elevation_samples_500m.csv','terrain/terrain_attention_points.geojson','mission_fixture/synthetic_unit_route.geojson','mission_fixture/synthetic_drone_waypoints.geojson','mission_fixture/synthetic_route_branches.geojson','mission_fixture/synthetic_cue_zones.geojson','mission_fixture/synthetic_no_go_zones.geojson'];
await writeJSON(path.join(OUT,'manifest.json'),{bundle:'palantir_sunol_aoi_upload',created_at:retrieved_at,aoi:{name:AOI_NAME,bbox:BBOX},files,counts,provenance:['OpenStreetMap Overpass','California Energy Commission ArcGIS','HIFLD ArcGIS','USGS EPQS','Synthetic mission fixtures'],safety_scope:'Planning-only ISR demo. Excludes strike/engage/kinetic/target-selection/weapon-release/real drone control/MAVLINK/GCS/hardware-control.'});
await fs.writeFile(path.join(OUT,'README.md'),`# Palantir Sunol AOI Upload Bundle\n\nOffline-uploadable bundle for ${AOI_NAME}.\nGenerated at: ${retrieved_at}.\nSee manifest.json for counts and provenance.\n`);
await fs.writeFile(path.join(OUT,'PALANTIR_UPLOAD_PROMPT.md'),`# Palantir Upload Prompt\n\nCreate object/map layers for AOI, power infrastructure, roads, buildings, terrain features, terrain attention points, no-go zones, unit route, drone waypoints, route branches, and cue zones.\n\nUse WGS84 and preserve source_name/source_url/retrieved_at/provisional fields.\n\nExplicitly exclude strike, engage, kinetic, target-selection, weapon-release, real drone control, MAVLINK/GCS, and hardware-control workflows.\n`);
console.log('Generated',OUT);
